export interface APIMonitorConfig {
  rateLimitThreshold?: number;
  predictionWindow?: number;
  apiUrl?: string;
}

export interface RefactorConfig {
  targetLanguage?: string;
  rules?: Array<'performance' | 'idiom' | 'optimization' | 'async'>;
}

export interface TrafficRecord {
  endpoint: string;
  method: string;
  timestamp: number;
  responseTime: number;
  statusCode: number;
  headers: Record<string, string>;
}

export interface PredictionResult {
  endpoint: string;
  riskLevel: 'low' | 'medium' | 'high';
  predictedFailure: boolean;
  rateLimitApproaching: boolean;
  suggestedAlternatives: string[];
  confidence: number;
}

export interface RefactorSuggestion {
  type: 'performance' | 'idiom' | 'optimization' | 'async' | 'error';
  description: string;
  originalCode: string;
  suggestedCode: string;
  line: number;
  severity: 'low' | 'medium' | 'high' | 'critical';
}
